---InitEquipAttributeData
---初始化卡牌属性数据
function UICultivateEquipSuitDescAndAttrNodeMB:InitEquipAttributeData()
    local cardDojo               = self:GetCardDojo()
    local basicAttributeDataList = {}
    -- local basicAttributes        = cardConfMgr:GetBasicAttrs()
    local star                   = checkNumber(cardDojo.star)
    local cardLevel              = checkNumber(cardDojo.cardLevel)
    local emptyEquipIdList = {0, 0, 0, 0}
    local equipIdList = self:GetEquipIdList()
    local isOwnEquip = false
    for i, v in ipairs(equipIdList) do
        if checkNumber(v) > 0 then
            isOwnEquip = true
            break
        end
    end

    local playerEquipCoreId = self:GetEquipCoreId()
    local isOwnCore = playerEquipCoreId > 0

    local preParams = {star = star, cardLevel = cardLevel, equipIdList = emptyEquipIdList, playerEquipCoreId = 0}
    local curParams = {star = star, cardLevel = cardLevel, equipIdList = equipIdList, playerEquipCoreId = playerEquipCoreId}
    FormulaUtils.CompareBasicAttrs(cardDojo, cardDojo, function (basicVo, emptyEquipAttr, equipAttr, index)
        local isShowAddAttr = false
        local attrNum = 0
        if isOwnEquip or isOwnCore then
            attrNum = equipAttr - emptyEquipAttr
            isShowAddAttr = math.abs(attrNum) > 0
        end
        if isShowAddAttr then
            table.insert(basicAttributeDataList, {
                basicConf = basicVo,
                curAttr = attrNum
            })
        end
    end, preParams, curParams)
    
    self.basicAttributeDataList = basicAttributeDataList

end

function UICultivateEquipSuitDescAndAttrNodeMB:InitSuitDesc()
    local suitInfoList = {}
    ---@type EquipmentComponent
    local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    local playerEquipCoreId = self:GetEquipCoreId()

    if playerEquipCoreId > 0 then
        ---@type EquipmentCoreDojo
        local equipmentCoreDojo = equipComp:GetEquipCoreById(playerEquipCoreId)

        local equipmentCoreId = equipmentCoreDojo.equipmentCoreId
        ---@type GoodsVo
        local goodsVo = goodsConfMgr:GetGoodsVoById(equipmentCoreId)
        ---@type EquipCoreVo
        local equipCoreVo = cardConfMgr:GetEquipCoreVoById(equipmentCoreId)
        local occupationId = equipCoreVo.occupationId
        local icon
        if occupationId > 0 then
            ---@type JobVo
            local jobVo = cardConfMgr:GetCardCareerRowByType(occupationId)
            icon = jobVo.icon
        end
        table.insert(suitInfoList, {
            suitName = goodsVo.name,
            icon = icon,
        })

        --- @field suits <suitId, partCount>
        local suits = equipComp:GetEquipSuitInfoByEquipIdList(self:GetEquipIdList(), 2)
        local suitList = EquipUtils.GetAllSuitEffectList(equipmentCoreId, suits)
        for i, suitData in ipairs(suitList) do
            table.insert(suitInfoList, {
                suitCount = suitData.effectNum,
                suitDesc = suitData.desc,
                activation = suitData.activation
            })
        end

    end
    self.suitInfoList = suitInfoList
end


