---OnGetAttrItemByIndex
---@param listView SuperScrollView.LoopGridView
---@param index number
---@return SuperScrollView.LoopGridView
function UICultivateEquipSuitDescAndAttrNodeMB:OnGetAttributeItemByIndex(listView, index, row, column)
    if index < 0 then return nil end

    local cell = listView:NewListViewItem(PrefabNameAttributeNode)
    ---- cell绑定的脚本
    local cellViewMB = GetLuaBehaviour(cell.gameObject, PrefabPathAttributeNode)
    if KTool.IsNull(cellViewMB) then return cell end

    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        if cellViewMB.Env == nil then
            cellViewMB:Init()
        end
    end

    ---@type UICultivateAttributeNode
    local env = cellViewMB.Env
    if env then
        local position = index + 1
        local subAttr = self.basicAttributeDataList[position]
        local basicConf = subAttr.basicConf
        env:RefreshUI(basicConf, subAttr.curAttr, nil, basicConf.isConversion)
        --env:RefreshBgStatus(index % 2 == 0 and 1 or 2)
    end

    return cell
end

---OnGetSuitDescItemByIndex
---@param listView SuperScrollView.LoopGridView
---@param index number
---@return SuperScrollView.LoopGridView
function UICultivateEquipSuitDescAndAttrNodeMB:OnGetSuitDescItemByIndex(listView, index, row, column)
    if index < 0 then return nil end
    local position = index + 1

    local PrefabName, PrefabPath
    if position == 1 then
        PrefabName, PrefabPath = PrefabNameSuitTitleNode, PrefabPathSuitTitleNode
    else
        PrefabName, PrefabPath = PrefabNameSuitDescNode, PrefabPathSuitDescNode
    end

    local cell = listView:NewListViewItem(PrefabName)

    ---- cell绑定的脚本
    ---@type UICultivateEquipSuitDescNodeMB
    local cellViewMB = GetLuaBehaviour(cell.gameObject, PrefabPath)
    if KTool.IsNull(cellViewMB) then return cell end
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        if cellViewMB.Env == nil then
            cellViewMB:Init()
        end
    end

    ---@type UICultivateEquipSuitDescNodeMB
    local env = cellViewMB.Env
    if env then
        local data = self.suitInfoList[position]
        if position == 1 then
            env:RefreshUI(data.suitName, data.icon)
        else
            env:RefreshUI(data.suitCount, data.suitDesc, data.activation)
        end

    end

    return cell
end

function UICultivateEquipSuitDescAndAttrNodeMB:RefreshUI(equipIdList, playerEquipmentCore, cardDojo)
