function UICultivateEquipSuitDescAndAttrNodeMB:RefreshSuitDescNode()
    local isSuitSkillDesc = self.selectType == SelectType.SuitSkillDesc
    local isShowAttr = self.selectType == SelectType.AttributeDesc
    KTool.SetActive(self.DescNode.gameObject, isSuitSkillDesc)
    KTool.SetActive(self.AttributeNodeScrollRoot.gameObject, isShowAttr)

    if isShowAttr then
        self:RefreshAttributeNodes()
    elseif isSuitSkillDesc then
        self:RefreshSuitDesc()
    end

