---RefreshAttrNodes
---刷新属性节点列表
function UICultivateEquipSuitDescAndAttrNodeMB:RefreshAttributeNodes()
    local AttributeScrollView    = self.AttributeScrollView
    local basicAttributeDataList = self:GetBasicAttributeDataList()
    local count = #basicAttributeDataList
    local isShow = count > 0
    KTool.SetActive(AttributeScrollView.gameObject, isShow)
    self:RefreshEmptyNode(not isShow, localize("暂无属性加成"))
    if not isShow then
        return
    end

    if not AttributeScrollView.IsListViewInit then
        AttributeScrollView:InitGridView(count, Bind(self, self.OnGetAttributeItemByIndex))
        return
    end
    GameUtils.ReloadData(AttributeScrollView, count)
end

---RefreshSuitDesc
---刷新套装描述
function UICultivateEquipSuitDescAndAttrNodeMB:RefreshSuitDesc()
    local suitList   = self:GetSuitDescList()
    local count      = #suitList
    local isShowDesc = count > 0
    local SuitDescScrollView = self.SuitDescScrollView
    KTool.SetActive(SuitDescScrollView.gameObject, isShowDesc)
    self:RefreshEmptyNode(not isShowDesc, localize("暂无套装效果"))
    if not isShowDesc then
        return
    end

    if not SuitDescScrollView.IsListViewInit then
        SuitDescScrollView:InitListView(count, Bind(self, self.OnGetSuitDescItemByIndex))
        return
    end
    GameUtils.ReloadData(SuitDescScrollView, count)
end

function UICultivateEquipSuitDescAndAttrNodeMB:RefreshEmptyNode(isShow, text)
    KTool.SetActive(self.EmptyTipNode.gameObject, isShow)
    if not isShow then return end
    ---@type EmptyNodeMB
    local env = CfUtils.GetLuaScr(self.EmptyTipNode.gameObject, "Game.Behaviours.EmptyNodeMB")
    if not isNull(env) then
        env:SetText(text)
    end
end

